/* Block recipe: composition only. All selectors stay inside its root. */
.kit-collection {
  --kit-filter-width: var(--commerce-filter-width);
  --kit-layout-gap: var(--commerce-layout-gap);
  --kit-grid-gap: var(--commerce-column-gap);
  --kit-image-surface: var(--surface-base);
  box-sizing: border-box;
  width: 100%;
  padding: var(--card-padding-lg) var(--container-padding-lg);
  background: var(--background-primary);
  color: var(--text-primary);
  font-family: var(--font-family-body);
  font-size: var(--typography-caption-size);
}
.kit-collection *, .kit-collection *::before, .kit-collection *::after { box-sizing: border-box; }
.kit-collection h2, .kit-collection h3, .kit-collection h4, .kit-collection p { margin: 0; }
.kit-collection .kit-intro { gap: var(--inline-gap-lg); margin-block-end: var(--space-6); }
.kit-intro > .flex > .text-muted { font-size: var(--typography-micro-size); font-weight: var(--font-weight-semibold); letter-spacing: var(--letter-spacing-widest); }
.kit-collection .kit-intro h2 { font-size: var(--typography-collection-title-size); line-height: var(--line-height-tight); letter-spacing: var(--letter-spacing-tighter); }
.kit-intro > p { font-size: var(--typography-micro-size); margin-block-end: var(--space-1); }
.kit-stop { color: var(--brand-primary); }
.kit-collection .kit-tabs { margin-block-end: var(--space-8); }
.kit-collection .kit-layout { gap: var(--kit-layout-gap); }
.kit-collection .kit-filters { flex: 0 0 var(--kit-filter-width); min-width: 0; }
.kit-collection .kit-filter-heading { margin-block-end: var(--space-5); }
.kit-filter-heading h3 { font-size: var(--typography-caption-size); }
.kit-collection .kit-filter-section { gap: var(--form-option-gap); padding-block: var(--card-padding-sm) var(--card-padding); border-block-start: var(--border-width-thin) solid var(--border-default); }
.kit-filter-section h4, .kit-note h4 { font-size: var(--typography-micro-size); font-weight: var(--font-weight-semibold); }
.kit-collection .checkbox-label { width: 100%; font-size: var(--typography-micro-size); }
.kit-collection .checkbox-label .flex > span:last-child { color: var(--text-muted); font-size: var(--typography-micro-size); }
.kit-collection .choice-group .flex { gap: var(--space-1); }
.kit-filter-section > .flex > span { font-size: var(--typography-micro-size); }
.kit-collection .slider-header { position: absolute; width: var(--space-px); height: var(--space-px); overflow: hidden; clip-path: inset(50%); }
.kit-collection .kit-note { margin-block-start: var(--space-3); padding: var(--space-4); background: var(--kit-image-surface); gap: var(--stack-gap); }
.kit-note > span { font-size: var(--font-size-2xl); margin-block-end: var(--space-1); }
.kit-note p { font-size: var(--typography-micro-size); line-height: var(--line-height-relaxed); }
.kit-collection .kit-results { flex: 1 1 0; min-width: 0; gap: var(--space-5); }
.kit-collection .kit-toolbar { min-height: var(--button-min-height-sm); gap: var(--inline-gap); font-size: var(--typography-micro-size); }
.kit-muted { color: var(--text-muted); }
.kit-collection .kit-sort { flex-shrink: 0; }
.kit-sort label { white-space: nowrap; font-size: var(--typography-micro-size); color: var(--text-muted); }
.kit-collection .kit-sort .select { width: auto; max-width: calc(var(--grid-min) * 0.625); }
.kit-collection .kit-search { gap: var(--inline-gap); min-height: var(--form-height); padding-inline: var(--form-padding-x); border: var(--border-width-thin) solid var(--form-border); border-radius: var(--form-radius); background: var(--form-background); }
.kit-search > span:first-child { font-size: var(--font-size-2xl); line-height: var(--line-height-none); }
.kit-collection .kit-search .input { flex: 1; min-width: 0; }
.kit-search > .text-muted { flex-shrink: 0; font-size: var(--typography-micro-size); letter-spacing: var(--letter-spacing-widest); }
.kit-collection .kit-products { grid-template-rows: none; gap: var(--space-7) var(--kit-grid-gap); }
.kit-product { min-width: 0; }
.kit-product-link { display: block; color: inherit; text-decoration: none; }
.kit-product-link:focus-visible { outline: var(--focus-ring-width) solid var(--focus-ring-color); outline-offset: var(--focus-ring-offset); }
.kit-product-link:hover h3 { text-decoration: underline; text-underline-offset: var(--space-1); }
.kit-product-image { position: relative; }
.kit-collection .kit-concept { position: absolute; inset-block-start: var(--space-3); inset-inline-start: var(--space-3); background: var(--background-primary); color: var(--text-primary); font-size: var(--typography-micro-size); font-weight: var(--font-weight-regular); letter-spacing: var(--letter-spacing-widest); }
.kit-product-arrow { position: absolute; inset-block-end: var(--space-3); inset-inline-end: var(--space-3); display: grid; place-items: center; width: calc(var(--space-4) * 1.625); height: calc(var(--space-4) * 1.625); border-radius: var(--radius-full); background: var(--background-primary); color: var(--text-secondary); font-size: var(--typography-caption-size); }
.kit-collection .kit-product-copy { margin-block-start: var(--space-3); gap: var(--inline-gap-sm); }
.kit-product-copy > .text-muted { font-size: var(--typography-product-meta-size); }
.kit-collection .kit-product-copy h3 { min-width: 0; font-size: var(--typography-product-name-size); line-height: var(--line-height-normal); font-weight: var(--font-weight-regular); overflow-wrap: anywhere; }
.kit-product-copy .price { flex-shrink: 0; font-size: var(--typography-product-price-size); }
.kit-collection .kit-product-meta { margin-block-start: var(--space-3); font-size: var(--typography-product-meta-size); gap: var(--inline-gap-sm); }
.kit-collection .kit-mobile-filters { display: none; }
.kit-collection .kit-empty, .kit-collection .kit-selection { padding: var(--card-padding); border: var(--border-width-thin) solid var(--border-default); }
.kit-collection .kit-selection { margin-block-start: var(--space-8); }
@media (max-width: 64rem) {
  .kit-collection { padding: var(--card-padding); --kit-filter-width: calc(var(--space-4) * 10); --kit-layout-gap: calc(var(--space-4) * 1.5); }
  .kit-collection .kit-products { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@media (max-width: 48rem) {
  .kit-collection { padding: var(--space-5) var(--space-4); }
  .kit-collection .kit-intro { align-items: flex-start; }
  .kit-collection .kit-layout { flex-direction: column; }
  .kit-collection .kit-mobile-filters { display: inline-flex; margin-block-end: var(--space-5); }
  .kit-collection .kit-filters { display: none; width: 100%; flex-basis: auto; }
  .kit-collection .kit-filters-open { display: block; }
  .kit-collection .kit-results { width: 100%; }
  .kit-search > .text-muted { display: none; }
  .kit-product-copy > .flex { flex-wrap: wrap; }
  }
@media (max-width: 26rem) { .kit-collection .kit-products { grid-template-columns: minmax(0, 1fr); } }

export interface CollectionProduct {
  id: string;
  name: string;
  category: string;
  price: number;
  sizes: string[];
  color: string;
  colorName: string;
  inStock: boolean;
  image: string;
}
export const categories = ["Training wear", "Outerwear", "Accessories"];
export const sizes = ["XS", "S", "M", "L", "XL", "One size"];
export const products: CollectionProduct[] = [
  { id: "jersey", name: "Academy training jersey", category: "Training wear", price: 28, sizes: sizes.slice(0, 5), color: "#222722", colorName: "Black", inStock: true, image: "jersey" },
  { id: "tee", name: "Everyday training tee", category: "Training wear", price: 24, sizes: sizes.slice(0, 5), color: "#f6d82e", colorName: "Yellow", inStock: true, image: "tee" },
  { id: "zip", name: "Academy quarter zip", category: "Outerwear", price: 46, sizes: sizes.slice(0, 5), color: "#30312c", colorName: "Charcoal", inStock: true, image: "zip" },
  { id: "shorts", name: "Matchday training shorts", category: "Training wear", price: 22, sizes: sizes.slice(0, 5), color: "#222722", colorName: "Black", inStock: true, image: "shorts" },
  { id: "hoodie", name: "Clubhouse warm-up hoodie", category: "Outerwear", price: 54, sizes: sizes.slice(0, 5), color: "#d7d5c8", colorName: "Natural", inStock: false, image: "hoodie" },
  { id: "tote", name: "Academy kit tote", category: "Accessories", price: 18, sizes: ["One size"], color: "#252621", colorName: "Black", inStock: true, image: "tote" },
  { id: "longsleeve", name: "Long sleeve training top", category: "Training wear", price: 32, sizes: sizes.slice(0, 5), color: "#252b26", colorName: "Deep green", inStock: true, image: "longsleeve" },
  { id: "trackpants", name: "Everyday track pants", category: "Training wear", price: 38, sizes: sizes.slice(0, 5), color: "#2a2c27", colorName: "Charcoal", inStock: false, image: "trackpants" },
];
export interface CollectionFilters {
  tab: string;
  categories: string[];
  sizes: string[];
  maxPrice: number;
  inStock: boolean;
  query: string;
  sort: string;
}
export function defaultFilters(): CollectionFilters {
  return { tab: "all", categories: [], sizes: [], maxPrice: 100, inStock: false, query: "", sort: "featured" };
}
export function filterProducts(items: readonly CollectionProduct[], filters: CollectionFilters): CollectionProduct[] {
  const query = filters.query.trim().toLocaleLowerCase("en-GB");
  const result = items.filter(product =>
    (filters.tab === "all" || product.category === filters.tab) &&
    (!filters.categories.length || filters.categories.includes(product.category)) &&
    (!filters.sizes.length || filters.sizes.some(size => product.sizes.includes(size))) &&
    product.price <= filters.maxPrice && (!filters.inStock || product.inStock) &&
    `${product.name} ${product.category}`.toLocaleLowerCase("en-GB").includes(query));
  if (filters.sort === "price-low") result.sort((a, b) => a.price - b.price);
  if (filters.sort === "price-high") result.sort((a, b) => b.price - a.price);
  if (filters.sort === "name") result.sort((a, b) => a.name.localeCompare(b.name, "en-GB"));
  return result;
}
